from typing import List

def can_form_rectangle(sticks: List[int], min_length: int) -> bool:
    """
    Check if sticks can form a rectangle with at least one side of length min_length.
    """
    for i in range(len(sticks)):
        for j in range(i + 1, len(sticks)):
            if sticks[i] == sticks[j] or sticks[i] + sticks[j] < sticks[min_length]:
