import sys

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def calculate_partitions(n, majority, minority):
    if majority >= n or minority >= n:
        return 0
    if n <= 4:
        return factorial(n) // (factorial(n - 1) * factorial(2))

    binary_majority = []
    binary_minority = []
    max_bit = 0
    majority_set = set()
    minority_set = set()

    for i in range(n):
        if (majority >> i) & 1:
            binary_majority.append(i)
            majority_set.add(i)
        if (minority >> i) & 1:
            binary_minority.append(i)
            minority_set.add(i)
        max_bit = max(max_bit, len(binary_majority), len(binary_minority))

    shift_majority_to_end = max_bit - len(binary_majority)
    shift_minority_to_end = max_bit - len(binary_minority)
    dominant_bit = (n - max(shift_majority_to_end, shift_minority_to_end))

    is_majority_left = dominant_bit > 0
    dominant_arrival_bit = dominant_bit - minority_set.bisect_right(max_bit - n)
    arrival_bit = dominant_bit - majority_set.bisect_left(max_bit - n)
    is_minority_left = majority_set.bisect_right(minority_set.end - dominant_arrival_bit - dominant_bit - shift_majority_to_end) == dominant_arrival_bit + dominant_bit

    if not is_majority_left or (is_majority_left and not is_minority_left):
        return 0

    return factorial(n) // (factorial(n - shift_majority_to_end) * factorial(shift_majority_to_end) * factorial(n - shift_minority_to_end) * factorial(shift_minority_to_end))

