def solve(k, n, m, color_counts, dp):
    if dp[n][m][color_counts] != -1:
        return dp[n][m][color_counts]

    grid = []
    for _ in range(n):
        row = list(map(int, input().split()))
        grid.append(row)

    coloring = [[-1] * m for _ in range(n)]

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 0:
                if r != 0 and c != 0:
                    coloring[r][c] = (coloring[r][c-1] if coloring[r][c-1] != -1 else 0
                                      + coloring[r-1][c] if coloring[r-1][c] != -1 else 0
                                      + color_counts)
                color_counts += 1
                coloring[r][c] = color_counts

    dp[n][m][color_counts] = 1

    for r in range(n-1, -1, -1):
        for c in range(m-1, -1, -1):
            if grid[r][c] != 0:
                continue

            a, b, c, d = coloring[r][c]

            diff_row = max(0, a - b)
            if diff_row != 0:
                dp[r][c][color_counts] += mod_pow(k, n - r - diff_row, mod)
                dp[r][c][color_counts] %= mod

            diff_col = max(0, c - d)
            if diff_col != 0:
                dp[r][c][color_counts] += mod_pow(k, m - c - diff_col, mod)
                dp[r][c][color_counts] %= mod

    dp[n][m][color_counts] %= (10**9 + 7)

    return dp[n][m][color_counts]

