def sieve(limit):
    primes = [1] * (limit + 1)
    for i in range(2, limit + 1):
        if primes[i] == 1:
            primes[i] = i
            if not (i * i) > limit:
                for n in range(i * i, limit + 1, i):
                    primes[n] = i
    return [p for p, e in zip(range(limit + 1), primes) if e == 1]

