def is_permutation_stay_same(a, n):
    # Final permutation should be identical to the original
    if sorted(a) != list(range(1, n + 1)):
        return "NO"

    # Count number of swaps needed
    swaps_needed = 0
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] > a[j]:
                swaps_needed += 1

    # Check if all pairs can be swapped
    if swaps_needed % 2 == 0:
        return "YES"
    else:
        return "NO"

