def calculate_cost(N, C, M, pairs):
    cost = 0
    for U, V in pairs:
        if U == V:
            cost += C
        elif (U, V) in pairs:
            cost += 0
        else:
            cost += C
    return cost

# Main function to find optimal model
def find_optimal_model(T, N, C, M, pairs):
    best_cost = sys.float_info.max
    optimal_pairs = []
    for _ in range(T):
        models = []
        time_penalty = 0
        for j in range(N):
            flyovers = [j, v for u, v in pairs]
            if len(flyovers) == N:
                cost = calculate_cost(N, C, sum((n-1)*C for n in range(N,N+1)), pairs)
                time_penalty = sum(C*(n-1)*(n+1) for n in range(N+1,N+2))
            else:
                models.append((flyovers, cost))
        for model in models:
            cost = sum(model[1]) + len(model[0]) * C
            if cost < best_cost:
                best_cost = cost
                optimal_pairs = model
    return best_cost, optimal_pairs

