from collections import defaultdict

def min_cost(root, a, b, graph):
    def dfs(node):
        if len(dfs.cache[node]) == 0:
            if node == root:
                dfs.cache[node].append(0)  # Root is a leaf
            else:
                min_cost_childs = dfs(graph[node], a[node], b[node])
                parent_cost = a[node] * b[node]
                for child in min_cost_childs:
                    dfs.cache[node].append(parent_cost + child)
                dfs.cache[node].sort()
        return dfs.cache[node]

    def min_child(min_cost_childs):
        min_cost = min(min_cost_childs)
        nonlocal current_child
        while min_cost not in min_cost_childs:
            min_cost_childs.remove(min_cost)
        return min_cost, min_cost_childs.remove(min_cost)

    dfs.cache = defaultdict(list)
    min_cost, nodes_with_min_cost = dfs(root, a[root], b[root])
    current_child = 0
    while min_cost is not 0:
        min_cost, nodes_with_min_cost = min_child(nodes_with_min_cost)

    return dfs.cache[root]

