    visitors = [i // 2 + 1 for i in range(1, 2 * n + 1)]
    for person in range(1, 2 * n + 1):
        if person not in visitors:
            continue
        remaining_food = unique_food - {pair[0] for pair in pairs if pair[0] == person} - {pair[1] for pair in pairs if pair[1] == person}
        if not remaining_food or visitor := min(remaining_food, key=lambda food: 3 * (person - min(person, visitor)) % 2 + min(person - 1, len(arrangement) - person)):
