MOD = 1000000007

def count_paintings(n, m, k):
    # Initialize the DP table
    dp = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(1, k + 1):
        dp[i][i] = 1
    for length in range(2, k + 1):
        for i in range(k + 1):
            for j in range(i, k + 1):
                if j > i:
                    dp[j][length] = (dp[j][length] + (j - i) * dp[i][length - 1]) % MOD

    total_paintings = 0

    # Follow the path matrix and sum steps for each row
    matrix = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(n - 1, -1, -1):
        total_paintings = (total_paintings + total_steps(matrix, i)) % MOD
    return total_paintings


def total_steps(matrix, end_row):
    total_steps = 1
    for color in range(1, k + 1):
        total_steps = (total_steps + matrix[color][end_row]) % MOD
    return total_steps

