import sys

def find_min_moves(m, n, positions):
    total_positions = sum(positions)
    if n == 1:
        return 0

    min_moves = sys.maxsize
    for i in range(m):
        next_position = (positions[-1] + m - 1) % m
        if next_position in positions:
            min_moves = min(min_moves, total_positions - next_position)
        else:
            min_moves = min(min_moves, i)
            break

    for direction in ["clockwise", "counterclockwise"]:
        positions_used = set()
        current_position = 0
        for _ in range(n):
            if direction == "clockwise":
                next_position = (current_position + m - 1) % m
            else:
                next_position = (current_position - 1) % m
            if next_position in positions_used:
                break
            positions_used.add(next_position)
            current_position = next_position
        else:
            min_moves = min(min_moves, len(positions) - positions_used)

    return min_moves


