from heapq import heappush, heappop

def dijkstra(nodes, edges):
    n = nodes + 1
    dist = defaultdict(lambda: float('inf'))
    dist[1] = 0
    pq = [(-1, 1)]

    while pq:
        _, node = heappop(pq)
        if node > 1:
            for child in edges[node]:
                if dist[node] + (nodes - 2) * (child[1] if len(child) > 1 else 0) < dist[child]:
                    dist[child] = dist[node] + (nodes - 2) * (child[1] if len(child) > 1 else 0)
                    heappush(pq, (dist[child], child))
    return list(dist.values())[1:n]

