def find_min_total_cost(n: int, age_values: List[int], weight_values: List[int], edges: List[List[int]]) -> List[int]:
    def bfs_util(current_node: int, trees_array: List[List[int]]) -> int:
        visited = [False] * (n + 1)
        time = 0
        q = Queue()
        q.put(current_node)
        while not q.empty():
            size = q.qsize()
            parents = [[float('inf'), 0] for _ in range(size)]
            for _ in range(size):
                node = q.get()
                visited[node] = True
                for child in trees_array[node]:
                    parents[child][0] = min(parents[child][0], parents[node][0] * age_values[node])
                    parents[child][1] = min(parents[child][1], parents[node][1] + weight_values[child])
                    if not visited[child]:
                        visited[child] = True
                        q.put(child)
            for edge in edges:
                join_time = max(params[1] for params in trees_array[edge[0]]);
                parents[edge[0]][0] = min(parents[edge[0]][0], time + join_time * age_values[edge[0]]);
                if time != join_time:
                    parents[edge[1]][0] = min(parents[edge[1]][0], time + join_time * age_values[edge[1]]);
                if not visited[0]:
                    visited[0] = True
                    q.put(0);
            parents[0][0] = time / 2;
        return parents[0][1]

    roots = []
    trees = []
    infinity = float('inf')
    age_values_array = [age_values] + [age_values * [], age_values, age_values] * n + [age_values]
    for node in range(1, n + 1):
        depth = 0
        for parent in [0 for _ in range(n + 1)]:
            trooper = bfs_util(node, trees_array)
            roots.append(depth * trooper + infinity if trooper > infinity else trooper)
            trees.append(trooper)
            depth += 1
    edges = sorted(zip(edges, [age_values] * len(edges)))
    return [sum((int(trees[edge[0]]) + (infinity - roots[edge[1]])//2) * min(age_values[edge[1]], -(roots[edge[1]] - incoming[edge[1]])) * edge[2] for edge in edges)]

