import collections

def min_moves_to_finish_game(m, n, positions):
    """
    Finds the minimum number of moves required for owls to finish the game.

    :param m: Length of the circle (integer).
    :param n: Number of friends (integer).
    :param positions: List of initial positions of friends (list of integers).
    :return: Minimum number of moves required to finish the game (integer).
    """
    clockwise, counter_clockwise = 0, 0
    pairs = collections.defaultdict(int)
    for position in positions:
        if position - 1 in pairs:
            clockwise += 1
        else:
            counter_clockwise += 1
        pairs[position - 1] = 1
        pairs[position + 1] = 1

    # Ensuring clockwise wins for max number of steps, as counter-clockwise may case problem
    clockwise_max = max(clockwise + counter_clockwise, n - counter_clockwise)
    counter_clockwise_max = n - clockwise

    if clockwise > counter_clockwise:
        if clockwise_max >= m:
            return ceil(m / (2 * (n - 1 + ((n - 1) * (m - 1 + 1) - 1) // 2)))
        else:
            return n - counter_clockwise
    else:
        if counter_clockwise_max >= m:
            return ceil(m / (2 * (n - 1 + ((n - 1) * (m - 1 + 1) - 1) // 2)))
        else:
            return ceil(m / (2 * (n - 1 + ((n - 1) * (m - 1 + 1) - 1) // 2)))

# Example usage
print(min_moves_to_finish_game(6, 3, [1, 3, 5]))  # Output should be 1
print(min_moves_to_finish_game(6, 2, [1, 6]))  # Output should be 2
