from itertools import permutations

def can_swap(permutation):
    n = len(permutation)
    for i in range(n):
        for j in range(i + 1, n):
            if permutation[i] > permutation[j]:
                # Find all indices greater than i
                for k in range(i + 1, n):
                    if permutation[i] > permutation[k]:
                        # Swap permutation[i+1] with permutaion[k]
                        permutation[i + 1], permutation[k] = permutation[k], permutation[i + 1]
                        # Attempt to arrange the new permutation
                        if permutation == list(range(1, n + 1)):
                            return "YES"
                        # Swap back and continue with next combination
                        else:
                            permutation[i + 1], permutation[k] = permutation[k], permutation[i + 1]
    return "NO"

def swap_op(pos0, pos1, permutation):
    temp = permutation[pos0]
    permutation[pos0] = permutation[pos1]
    permutation[pos1] = temp
    return permutation

def find_all_swaps(permutation):
    swaps = 0
    for i in range(len(permutation)):
        for j in range(i + 1, len(permutation)):
            if permutation[i] > permutation[j]:
                for k in range(i + 1, len(permutation)):
                    if permutation[i] > permutation[k]:
                        yield swap_op(i, k, permutation), swaps + 1

n = int(input().strip())
