import sys

def compute_pairs(max_A, max_B, cuts):
    dp = [0] * (max_A + max_B + 1)
    dp[0] = 1

    for i in range(1, max_A + 1):
        for j in range(1, max_B + 1):
            for c in cuts:
                if i >= c[1] and j >= c[0]:
                    dp[i + j] += dp[i] * c[2]

    return sum(dp) - dp[max_A + max_B]

